41	    const t = document.querySelector('x-timer');
42	    if (!t) return;
43	    const left = t.left;
44	    if (left <= 0) {
45	      running = false;
46	      if (timer) timer.stop();
47	      if (mode === 'work') { sessions += 1; notify('Session done!'); }
48	      return;
